const separateFilterMeta=filterMeta,separateAvailableFilters=availableFilters,separateEnsureRules=ensureRules;
filterHints.fieldFilters='Choose any available field, such as Closed Shipments or Shipment Type. Comparisons follow its data type. Combine conditions with AND or OR.';
filterMeta=function(kind,id){if(kind==='fieldFilters'&&!fby(id))return separateFilterMeta('keyFilters',id);return separateFilterMeta(kind,id)};
availableFilters=function(p,kind){if(kind!=='fieldFilters')return separateAvailableFilters(p,kind);return [...separateAvailableFilters(p,'fieldFilters'),...separateAvailableFilters(p,'keyFilters')].filter((m,i,a)=>a.findIndex(x=>x.id===m.id)===i)};
ensureRules=function(p){const rules=separateEnsureRules(p);if(!p.unifiedFilters){rules.fieldFilters=[...rules.keyFilters,...rules.fieldFilters.map((r,i)=>({...r,join:i===0?'AND':r.join}))];rules.keyFilters=[];p.unifiedFilters=true}return rules};
const sampleFilterValues={shipment_type:'COD',delivery_service:'SDD',pdd_status:'Same day',client:'Client A'};
programs.forEach(p=>{ensureRules(p);p.metrics={...sampleFilterValues,...p.metrics}});
const unifiedBlankProgram=blankProgram;blankProgram=function(type=0){const p=unifiedBlankProgram(type);ensureRules(p);p.metrics={...sampleFilterValues,...p.metrics};return p};
sampleInputs=function(p){const ids=[...new Set([p.primary,...p.others,p.payout,...ensureRules(p).fieldFilters.map(r=>r.field)])];return ids.map(id=>{const meta=filterMeta('fieldFilters',id);const text=meta.type==='Character';return `<label class="label" for="metric-${esc(id)}">${esc(meta.label)}</label><input id="metric-${esc(id)}" type="${text?'text':'number'}" ${text?'':'step="any"'} data-metric="${esc(id)}" data-sample-type="${meta.type}" value="${esc(p.metrics[id]??(text?'':0))}">`}).join('')+'<button class="button primary" id="applyMetrics">Update preview</button><p class="quiet">Sample values for evaluating the configured conditions.</p>'};
bindMetrics=function(){document.getElementById('applyMetrics')?.addEventListener('click',()=>{const id=Number(document.getElementById('sampleProgram').value),p=programs.find(x=>x.id===id);const inputs=[...document.querySelectorAll('[data-metric]')];if(inputs.some(x=>!x.value.trim()||(x.dataset.sampleType!=='Character'&&!Number.isFinite(Number(x.value))))){toast('Enter valid sample values.');return}inputs.forEach(x=>p.metrics[x.dataset.metric]=x.dataset.sampleType==='Character'?x.value:Number(x.value));render();document.getElementById('sampleProgram').value=id;document.getElementById('sampleInputs').innerHTML=sampleInputs(p);bindMetrics()})};
detailsFilterRules=function(p){const rules=ensureRules(p).fieldFilters;return rules.length?`<li>${esc(expressionText('fieldFilters',rules))}.</li>`:''};
render();
